module cdc_2phase #(
  parameter WIDTH = 1
)(
  input                  src_rst_ni,
  input                  src_clk_i,
  input      [WIDTH-1:0] src_data_i,
  input                  src_valid_i,
  output                 src_ready_o,

  input                  dst_rst_ni,
  input                  dst_clk_i,
  output     [WIDTH-1:0] dst_data_o,
  output                 dst_valid_o,
  input                  dst_ready_i
);

  // Internal signals
  logic [WIDTH-1:0] src_data_sync;
  logic             src_valid_sync;
  logic             src_valid_meta;
  logic             dst_valid_meta;

  // Synchronizers for src_valid_i to dst_clk_i domain
  always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
    if (!dst_rst_ni) begin
      src_valid_meta <= 1'b0;
      src_valid_sync <= 1'b0;
    end else begin
      src_valid_meta <= src_valid_i;
      src_valid_sync <= src_valid_meta;
    end
  end

  // Synchronizers for dst_valid_o to src_clk_i domain
  always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
    if (!src_rst_ni) begin
      dst_valid_meta <= 1'b0;
      dst_valid_o    <= 1'b0;
    end else begin
      dst_valid_meta <= dst_valid_o;
      dst_valid_o    <= dst_valid_meta;
    end
  end

  // Data synchronizer from src_clk_i to dst_clk_i domain
  always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
    if (!dst_rst_ni) begin
      src_data_sync <= '0;
    end else if (src_valid_i && !src_valid_sync) begin
      src_data_sync <= src_data_i;
    end
  end

  // Source side logic
  always_ff @(posedge src_clk_i or negedge src_rst_ni) begin
    if (!src_rst_ni) begin
      src_ready_o <= 1'b1;
    end else begin
      src_ready_o <= !src_valid_sync || (src_valid_sync && dst_ready_i);
    end
  end

  // Destination side logic
  always_ff @(posedge dst_clk_i or negedge dst_rst_ni) begin
    if (!dst_rst_ni) begin
      dst_data_o  <= '0;
      dst_valid_o <= 1'b0;
    end else if (src_valid_i && !src_valid_sync) begin
      dst_data_o  <= src_data_i;
      dst_valid_o <= 1'b1;
    end else if (dst_valid_o && dst_ready_i) begin
      dst_valid_o <= 1'b0;
    end
  end

endmodule
